// :app-tv — Archie TV, com.assistant.archie.tv, minSdk 26, Compose + tv-material (spec 15 §6.1).
// T0 builds the foundations (shell, theme, graph, first run); T1–T5 fill the screens. The module
// already depends on everything spec 15 §6.1 lists, so later work packages do not edit this file.
plugins {
    alias(libs.plugins.archie.android.app.tv)
    alias(libs.plugins.archie.android.compose)
    alias(libs.plugins.kotlin.serialization)   // Navigation 3 keys are @Serializable
    alias(libs.plugins.roborazzi)
}

android {
    namespace = "com.assistant.archie.tv"
    defaultConfig {
        applicationId = "com.assistant.archie.tv"
    }
    testOptions.unitTests.all { test ->
        // Roborazzi goldens at 1920×1080 px (960×540 dp @ xhdpi).
        test.maxHeapSize = "2g"
    }
}

roborazzi {
    // Spec 14 §6.4: goldens live in <module>/src/test/screenshots/.
    outputDir.set(layout.projectDirectory.dir("src/test/screenshots"))
}

dependencies {
    implementation(project(":core:data"))
    implementation(project(":core:design"))
    implementation(project(":core:markdown"))
    implementation(project(":core:voice-host"))
    implementation(project(":feature:chat"))
    implementation(project(":feature:toolcards"))
    implementation(project(":feature:sessions"))
    implementation(project(":feature:memory"))
    implementation(project(":feature:visuals"))
    implementation(project(":feature:settings"))

    implementation(libs.androidx.tv.material)
    implementation(libs.androidx.compose.material3)
    implementation(libs.androidx.compose.foundation)
    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.activity.compose)
    implementation(libs.androidx.lifecycle.runtime.compose)
    implementation(libs.androidx.lifecycle.viewmodel.compose)
    implementation(libs.androidx.lifecycle.process)
    implementation(libs.androidx.navigation3.runtime)
    implementation(libs.androidx.navigation3.ui)
    implementation(libs.androidx.lifecycle.viewmodel.navigation3)
    implementation(libs.kotlinx.collections.immutable)

    testImplementation(project(":core:testing"))
    testImplementation(libs.kotlinx.coroutines.test)
    testImplementation(libs.robolectric)
    testImplementation(libs.roborazzi)
    testImplementation(libs.roborazzi.compose)
    testImplementation(libs.roborazzi.junit.rule)
    testImplementation(libs.androidx.compose.ui.test.junit4)
    testImplementation(libs.androidx.test.core)
    testImplementation(libs.androidx.test.ext.junit)
    debugImplementation(libs.androidx.compose.ui.test.manifest)
}
